// englishJLPTVocabularyGrammar performs an exact source lookup. The field is
// part of the key because the same Indonesian text can have different meanings
// in different parts of a lesson.
func englishJLPTVocabularyGrammar(field, source string) (string, bool) {
	translated, ok := jlptEnglishCatalog[jlptEnglishSource{field: field, source: source}]
	return translated, ok
}
